    "/us/en/about/news/2022/features/focusing-on-her-mobility-": { "template": "news-detail", "metadata": { "title": "How Janet  recovered from a vertebral (spine) compression fracture ", "pageTitle": null, "description": "Janet worked with Dr. Smith to learn about the treatment options for her vertebral compression fracture, or \u2018VCF\u2019 for short.", "image": "/content/dam/stryker/about/news/2022/features/focusing-on-her-mobility-/IVS social media - July 2022_LinkedIn-REV_patient testimonial.jpg", "imageAlt": "Janet's vertebral compression fracture story", "tags": ["stryker:content-type/news", "stryker:content-type/news/Features"], "originallyPublished": "2023-02-06T13:55:38.000Z", "lastPublished": "2024-08-07T13:55:38.000Z", "contentID": "COMM-SJ-SYK-937939" }, "anchors": [], "disclaimer": null, "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/about/news/2022/features/game-changing-innovations": { "template": "news-detail", "metadata": { "title": "Game-changing innovations | Jeff\u2019s total shoulder replacement story", "pageTitle": null, "description": null, "image": "/content/dam/stryker/patients/patient-stories/jeff-brantley-1-31-22/jeff-bradley.png", "imageAlt": null, "tags": ["stryker:content-type/news", "stryker:content-type/news/Features", "stryker:content-type/news/patient-stories"], "originallyPublished": null, "lastPublished": "2022-06-29T13:37:00.000Z", "contentID": "SYK CORP 2022-06-104" }, "anchors": [], "disclaimer": null, "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/about/news/2022/features/hiking-back-to-health---rose-s-spine-surgery-story": { "template": "news-detail", "metadata": { "title": "Hiking back to health | Rose\u2019s spine surgery story", "pageTitle": null, "description": null, "image": "/content/dam/stryker/patients/patient-stories/rose-2-1-22/rose-patient-story.png", "imageAlt": null, "tags": ["stryker:content-type/news", "stryker:content-type/news/Features"], "originallyPublished": null, "lastPublished": "2022-02-10T19:54:43.000Z", "contentID": "SYK CORP 2022-01-09" }, "anchors": [], "disclaimer": '<p>In general, surgical treatment options presented by your surgeon are aimed at relieving pressure on nerve roots in an attempt to address pain. As with any surgery, spine surgery carries risk. See your surgeon to discuss your potential benefits and risks. Not all patients will have the same post-operative recovery and activity level. Individual results vary.</p>\r\n<p>References</p>\r\n<p>1. \u2018Low back pain fact sheet.\u2019&nbsp; National Institute of Neurological Disorders and Stroke. Date last modified: Mon, 2021-11-15 18:58. Accessed 17 January 2022. Website link: <a href="https://www.ninds.nih.gov/Disorders/Patient-Caregiver-Education/Fact-Sheets/Low-Back-Pain-Fact-Sheet">https://www.ninds.nih.gov/Disorders/Patient-Caregiver-Education/Fact-Sheets/Low-Back-Pain-Fact-Sheet</a></p>\r\n<p>GEN-WB-25_32292</p>', "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
