    "/us/en/about/news/2023/stryker-s-lobo-discusses-outlook-for-our-business--m-a-strategy-": { "template": "news-detail", "metadata": { "title": "Stryker\u2019s Lobo discusses outlook for our business, M&A strategy and future product innovation", "pageTitle": null, "description": null, "image": "/content/dam/stryker/about/news/2023/stryker\u2019s-lobo-discusses-outlook-for-our-business,-m-a-strategy-and-future-product-innovation/StrykerTalks23_4.11.23_1200x800.jpg", "imageAlt": "StrykerTalks23_4.11.23_1200x800", "tags": ["stryker:content-type/news/strykertalks-podcast", "stryker:content-type/news"], "originallyPublished": null, "lastPublished": "2023-04-13T14:59:33.000Z", "contentID": "COMM-GSNPS-SYK-630528" }, "anchors": [], "disclaimer": null, "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/about/news/2023/stryker-s-pangea-systems-receive-fda-clearance": { "template": "news-detail", "metadata": { "title": "Stryker\u2019s Pangea Systems Receive FDA Clearance ", "pageTitle": "Stryker\u2019s Pangea Systems Receive FDA Clearance ", "description": null, "image": "/content/dam/stryker/logos/stryker/stryker_logo2015_web.jpg", "imageAlt": "logo", "tags": ["stryker:content-type/news", "stryker:content-type/corporatenews"], "originallyPublished": null, "lastPublished": "2023-09-13T13:35:44.000Z", "contentID": "PGA-AR-1, 08-2023" }, "anchors": [], "disclaimer": "<p>This document is intended solely for healthcare professionals. A surgeon must always rely on his or her own professional clinical judgment when deciding whether to use a particular product when treating a particular patient. Stryker does not dispense medical advice and recommends that surgeons be trained in the use of any particular product before using it in surgery.</p>\r\n<p>The information presented is intended to demonstrate the breadth of Stryker\u2019s product offerings. A surgeon must always refer to the package insert, product label and/or instructions for use before using any of Stryker\u2019s products. Products may not be available in all markets because product availability is subject to the regulatory and/or medical practices in individual markets. Please contact your sales representative if you have questions about the availability of products in your area.</p>\r\n<p>Stryker Corporation or its affiliates own, use, or have applied for the following trademarks or service marks: Stryker. All other trademarks are trademarks of their respective owners or holders.</p>", "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/about/news/2023/stryker-s-q-guidance-system-for-cranial-applications-receives-fd": { "template": "news-detail", "metadata": { "title": "Stryker\u2019s Q Guidance System for cranial applications receives FDA clearance", "pageTitle": null, "description": null, "image": "/content/dam/stryker/about/news/2023/stryker\u2019s-q-guidance-system-for-cranial-applications-receives-fda-clearance/Q Guidance Cranial FDA 510k clearance.png", "imageAlt": "Q Guidance Cranial FDA 510k clearance", "tags": ["stryker:content-type/news", "stryker:content-type/news/in-the-news", "stryker:content-type/corporatenews"], "originallyPublished": null, "lastPublished": "2023-02-17T15:27:24.000Z", "contentID": "QGS-PR-3_34409" }, "anchors": [], "disclaimer": null, "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/about/news/2023/stryker-unveils-mako-total-knee-2-0-at-the-aaos-2023-annual-meet": { "template": "news-detail", "metadata": { "title": "Stryker unveils Mako Total Knee 2.0 at the AAOS 2023 Annual Meeting", "pageTitle": null, "description": null, "image": "/content/dam/stryker/logos/stryker/stryker_logo2015_web.jpg", "imageAlt": "stryker_logo2015_web", "tags": ["stryker:content-type/news", "stryker:content-type/news/in-the-news", "stryker:content-type/corporatenews"], "originallyPublished": null, "lastPublished": "2024-02-27T18:58:11.000Z", "contentID": "JR-MTKA-PRESS-560360" }, "anchors": [], "disclaimer": "<p>1. Illgen, R, Bukowski, B, Abiola, R, Anderson, P, Chughtai, M, Khlopas, A, Mont, M. Robotic assisted total hip arthroplasty: Outcomes at minimum two year follow up. Surgical Technology International. 2017 July 25; 30:365-372.</p>\r\n<p><br>\r\n2. Kayani B, Konan S, Tahmassebi J, Pietrzak JRT, Haddad FS. Robotic-arm assisted total knee arthroplasty is associated with improved early functional recovery and reduced time to hospital discharge compared with conventional jig-based total knee arthroplasty: a prospective cohort study. The Bone and Joint Journal. 2018;100-B:930-7.</p>\r\n<p><br>\r\n3. Burger JA, Kleeblad LJ, Laas N, Pearle AD. Mid-term survivorship and patient-reported outcomes of robotic-arm assisted partial knee arthroplasty. Bone Joint J. 2020;102-B(1):108-116.</p>", "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
