    "/us/en/about/news/2024/stryker-unveils-oculan-lighting-platform": { "template": "news-detail", "metadata": { "title": "Stryker unveils Oculan Lighting Platform to enhance surgical visualization and illumination", "pageTitle": null, "description": "Stryker unveiled the Oculan Lighting Platform, an innovative lighting solution designed to provide consistent, high-quality illumination, allowing surgeons to focus on delivering the highest standard of care.", "image": "/content/dam/stryker/about/news/2024/stryker-unveils-oculan-lighting-platform/20241119-Oculan-thumbnail.jpg", "imageAlt": "Oculan", "tags": ["stryker:content-type/news", "stryker:content-type/news/in-the-news", "stryker:content-type/corporatenews"], "originallyPublished": "2024-11-19T14:30:00.000Z", "lastPublished": "2024-11-19T15:51:33.000Z", "contentID": null }, "anchors": [], "disclaimer": null, "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
