    "/us/en/about/news/2026/features/stryker-releases-2025-comprehensive-report": { "template": "news-detail", "metadata": { "title": "Stryker releases 2025 Comprehensive Report", "pageTitle": null, "description": "Stryker is pleased to announce the publication of our 2025 Comprehensive Report, showcasing another year of progress toward our financial, environmental, social and governance commitments.", "image": "/content/dam/stryker/about/news/2026/stryker-releases-2025-comprehensive-report/images/comprehensive-report-2025-news-thumbnail.jpg", "imageAlt": "comprehensive-report-2025-news-thumbnail", "tags": ["stryker:content-type/news", "stryker:content-type/news/featured", "stryker:content-type/news/Features"], "originallyPublished": "2026-10-13T15:13:39.000Z", "lastPublished": "2026-10-13T15:13:39.000Z", "contentID": "MARK-GSNPS-SYK-4043451" }, "anchors": [], "disclaimer": null, "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/about/news/2026/features/what-everyone-should-know-about-arthritis": { "template": "news-detail", "metadata": { "title": "Myths, realities and real innovation: What everyone should know about arthritis", "pageTitle": null, "description": "We're clearing up the most common misconceptions about arthritis , because knowing the truth is the first step toward getting the right care.", "image": "/content/dam/stryker/about/news/2026/features/myths-realities-and-real-innovation-what-everyone-should-know-about-arthritis/Hero_Total_Knee_Cornhole2-news.jpg", "imageAlt": "Hero_Total_Knee_Cornhole-news", "tags": ["stryker:content-type/news/product-bulletins", "stryker:content-type/news/featured", "stryker:content-type/news"], "originallyPublished": "2026-06-10T15:46:25.000Z", "lastPublished": "2026-06-10T15:48:08.000Z", "contentID": null }, "anchors": [], "disclaimer": null, "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
