    "/us/en/about/news/features/patient-story-olivia": { "template": "news-detail", "metadata": { "title": "Finding her guide: Olivia\u2019s journey with Treacher Collins", "pageTitle": null, "description": null, "image": "/content/dam/stryker/about/news/olivia/Olivia__header.png", "imageAlt": null, "tags": ["stryker:content-type/news", "stryker:content-type/news/Features"], "originallyPublished": null, "lastPublished": "2019-12-18T20:22:09.000Z", "contentID": "CMF-NL-34_Rev.None_23109 SYK CORP 2019-11-14" }, "anchors": [], "disclaimer": "<p>A surgeon must always rely on his or her own professional clinical judgment when deciding whether to use a particular product when treating a particular patient. Stryker does not dispense medical advice and recommends that surgeons be trained in the use of any particular product before using it in surgery.</p>\r\n<p>The information presented is intended to demonstrate the breadth of Stryker product offerings. A surgeon must always refer to the package insert, product label and/or instructions for use before using any Stryker product. Products may not be available in all markets because product availability is subject to the regulatory and/or medical practices in individual markets. Please contact your Stryker representative if you have questions about the availability of Stryker products in your area</p>", "forms": [], "tabs": [], "cardLists": [], "missingAlt": ["/content/dam/stryker/about/news/olivia/Olivia__header.png", "/content/dam/stryker/about/news/olivia/Olivia__car.png", "/content/dam/stryker/about/news/olivia/Olivia.png"] },
