    "/us/en/sage/news/2022/health-affairs-urges-policy-makers-to-confront-pneumonia-threat": { "template": "news-detail", "metadata": { "title": "Health Affairs Forefront article urges policy makers to confront hospital-acquired pneumonia", "pageTitle": null, "description": null, "image": "/content/dam/stryker/sage/news/2022/Sage-Newsroom-Health-Affairs-Forefront.jpg", "imageAlt": "Patient in hospital bed", "tags": ["stryker:content-type/news", "stryker:content-type/news/sage/2"], "originallyPublished": null, "lastPublished": "2022-05-02T18:24:09.000Z", "contentID": "28976" }, "anchors": [], "disclaimer": "<p><b>Reference: 1.</b> Baker D, Giuliano K, Worzala C, Cloke A, Zawistowich L, Hospital Acquired Pneumonia Threatens Patient Safety \u2013 Policy Makers Must Act To Confront It, Health Affairs Forefront, https://www.healthaffairs.org/do/10.1377/forefront.20220418.65994 April 20, 2021.</p>", "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/sage/news/2022/infection-control-today-article-about-waterborne-pathogens": { "template": "news-detail", "metadata": { "title": "Infection Control Today highlights the importance of protecting against waterborne pathogens", "pageTitle": null, "description": null, "image": "/content/dam/stryker/sage/news/2022/Sage-Newsroom-ICT-water-article.jpg", "imageAlt": "Water faucet with pathogens", "tags": ["stryker:content-type/news", "stryker:content-type/news/sage/2"], "originallyPublished": null, "lastPublished": "2022-09-06T22:13:05.000Z", "contentID": "29109" }, "anchors": [], "disclaimer": '<p><b>References: 1. </b>Dyer J, Water: Life\u2019s Vital Necessity Can Also Be a Pool for Pathogens, Infection Control Today, April 2022, Vol. 26 Issue 3. Available at: <a href="https://www.infectioncontroltoday.com/view/water-life-s-vital-necessity-can-also-be-pool-pathogens" target="_blank" title="Water: Life\u2019s Vital Necessity Can Also Be a Pool for Pathogens">https://www.infectioncontroltoday.com/view/water-life-s-vital-necessity-can-also-be-pool-pathogens</a> Accessed: June 13, 2022.</p>', "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
